# 1. Naiwnie: O(2^n)
def fib_naiwnie(n):
    return n if n < 2 else fib_naiwnie(n - 1) + fib_naiwnie(n - 2)

# 2. Z gory na dol (spamietywanie): O(n) czasu, O(n) pamieci
def fib_memo(n, pamiec={}):
    if n < 2:
        return n
    if n not in pamiec:
        pamiec[n] = fib_memo(n - 1, pamiec) + fib_memo(n - 2, pamiec)
    return pamiec[n]

# 3. Z dolu do gory: O(n) czasu, O(1) pamieci
def fib_iteracyjnie(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
